C++ Syntax illustrating RVO/NRVO (Compiler behavior will vary):

```c++
class LargeObject {
public:
    LargeObject() { /* ...expensive constructor... */ }
    LargeObject(const LargeObject& other) { /* ...expensive copy constructor... */ }
    LargeObject(LargeObject&& other) noexcept { /* ...move constructor... */ }
    ~LargeObject() { /* ...destructor... */ }
};

LargeObject createLargeObject() {
    LargeObject obj;
    // ...some operations on obj...
    return obj; // RVO/NRVO *may* occur here
}

int main() {
    LargeObject myObj = createLargeObject(); // Object is created directly in myObj's memory if RVO/NRVO is applied
    return 0;
}
```

