#include <iostream>
#include <chrono>
#include <vector>
struct Expensive {
  std::vector<int> data;
  Expensive(int size) : data(size) { for (auto& x : data) x = 1; }
  Expensive(const Expensive& other) : data(other.data) {}
  Expensive(Expensive&& other) noexcept : data(std::move(other.data)) {}
};
Expensive createExpensive(int size) { Expensive e(size); return e; }
int main() {
  auto start = std::chrono::high_resolution_clock::now();
  Expensive x = createExpensive(1000000);
  auto end = std::chrono::high_resolution_clock::now();
  auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);
  std::cout << "Time taken: " << duration.count() << " ms\n";
  return 0;
}
